#include <iostream>
#include <stdexcept>

class Time {
private:
    int hour{0};
    int minute{0};
    int second{0};

public:
    Time() = default;

    void setTime(int h, int m, int s) {
        if ((h >= 0 && h < 24) && (m >= 0 && m < 60) && (s >= 0 && s < 60)) {
            hour = h;
            minute = m;
            second = s;
        } else {
            throw std::invalid_argument("hour, minute and/or second was out of range");
        }
    }

    int getHour() const { return hour; }
    int getMinute() const { return minute; }
    int getSecond() const { return second; }
};

int main() {
    Time t;
    t.setTime(13, 27, 6);
    std::cout << "Current time: " << t.getHour() << ":" << t.getMinute() << ":" << t.getSecond() << "\n";

    try {
        t.setTime(99, 99, 99);
    } catch (const std::invalid_argument& e) {
        std::cout << "Exception caught: " << e.what() << "\n";
    }

    std::cout << "Time after failed setTime: " << t.getHour() << ":" << t.getMinute() << ":" << t.getSecond() << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>

class Time {
private:
    int hour{0};
    int minute{0};
    int second{0};

public:
    Time(int h, int m, int s) : hour(h), minute(m), second(s) {}

    void printUniversal() const {
        std::cout << std::setfill('0')
                  << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second;
    }

    void printStandard() const {
        std::cout << ((hour == 0 || hour == 12) ? 12 : hour % 12) << ":"
                  << std::setfill('0')
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second
                  << (hour < 12 ? " AM" : " PM");
    }
};

int main() {
    Time morning(0, 5, 9);
    Time afternoon(13, 27, 6);

    std::cout << "Morning Universal: ";
    morning.printUniversal();
    std::cout << " | Standard: ";
    morning.printStandard();
    std::cout << "\n";

    std::cout << "Afternoon Universal: ";
    afternoon.printUniversal();
    std::cout << " | Standard: ";
    afternoon.printStandard();
    std::cout << "\n";

    return 0;
}
